const bridges = new WeakMap();
export class NativeBridgeError extends Error {
  constructor(code) { super(code); this.code = code; }
}
export function nativeSessionBridge(session) { return bridges.get(session); }
export function installNativeSessionBridge(session, options) {
  if (options?.isolated !== true || options.sessionId !== session.id || typeof options.flush !== "function") throw new NativeBridgeError("NATIVE_EXACT_ISOLATED_OPT_IN_REQUIRED");
  if (bridges.has(session)) throw new NativeBridgeError("NATIVE_ALREADY_INSTALLED");
  let acceptance = Promise.resolve();
  let writer;
  let epoch = Math.max(0, ...session.log.filter(e => e.type === 'native/window-intent').map(e => e.data.fencingEpoch ?? 0));
  let windowGate;
  const deferredWake = new Set();
  const acceptedEvents=session.log.filter(event=>event.type==='native/input-accepted');
  if(acceptedEvents.some(event=>event.data.preemptGeneration!==undefined
    &&(!Number.isSafeInteger(event.data.preemptGeneration)||event.data.preemptGeneration<1))) throw new NativeBridgeError('NATIVE_GENERATION_INVALID');
  const initialGeneration=acceptedEvents.reduce((max,event)=>Math.max(max,event.data.preemptGeneration??0),0);
  const announcedEvents=new Set(acceptedEvents.map(event=>event.seq));
  let sample;
  const listeners = new Set();
  const inputPolicies = new Set();
  const preempts = (agent, message) => message.source?.kind === 'user'
    || [...inputPolicies].some(policy => policy(agent, message) === true);
  const publishDurable=async(agent,wakeup)=>{
    await bridge.requireDurable();
    const pending=session.log.filter(event=>event.type==='native/input-accepted'&&!announcedEvents.has(event.seq));
    const nextGeneration=pending.reduce((max,event)=>Math.max(max,event.data.preemptGeneration??0),bridge.generation);
    if(nextGeneration>bridge.generation&&!bridge.hardAborted){
      bridge.generation=nextGeneration;
      sample?.abort(new NativeBridgeError('SAMPLING_PREEMPTED'));
    }
    for(const event of pending)announcedEvents.add(event.seq);
    if(pending.length)for(const listener of listeners)listener();
    if(pending.some(event=>(event.data.wakeup??wakeup)
      &&(!bridge.hardAborted||event.data.target==='next-turn'&&agent.phase.kind==='idle'))){
      if(windowGate?.isPaused())deferredWake.add(agent);
      else agent.wakeDriver();
    }
  };
  const bridge = {
    options,
    bindWindowGate(gate) { if (windowGate) throw new NativeBridgeError('WINDOW_COORDINATOR_ALREADY_INSTALLED'); windowGate = gate; },
    // Only the owner of the bound gate can release it, and never while a writer holds the surface. A hot-reloaded
    // coordinator hands the session over this way; until its successor binds, nothing fences reads here, so the
    // caller must keep the session's steps refused across the gap.
    unbindWindowGate(gate) {
      if (windowGate !== gate) throw new NativeBridgeError('WINDOW_COORDINATOR_NOT_BOUND');
      if (writer) throw new NativeBridgeError('NATIVE_WRITER_CAS_CONFLICT');
      windowGate = undefined;
    },
    assertWindowReadable() { windowGate?.assertReadable(); },
    assertCompactionAllowed() { windowGate?.assertCompactionAllowed(); },
    assertInputClaim() { windowGate?.assertReadable(); },
    windowParticipationFacts() { return { kind: 'native-window-writers-v1', sessionId: session.id,
      domains: ['input-claim', 'surface', 'compaction', 'tool-admission'], isolated: true }; },
    generation: initialGeneration,
    samplingGeneration: initialGeneration,
    activeEffects: 0,
    hardAborted: false,
    get surfaceRevision() { return session.log.filter(event => event.surfaceOp !== undefined).length; },
    get inputCursor() { return session.log.findLast(event => event.type === "native/input-accepted")?.seq ?? -1; },
    async requireDurable() {
      if (await options.flush(session) !== true) throw new NativeBridgeError("NATIVE_DURABILITY_UNAVAILABLE");
    },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    registerInputPreemption(policy) {
      if (typeof policy !== 'function') throw new NativeBridgeError('NATIVE_INPUT_POLICY_INVALID');
      inputPolicies.add(policy);
      return () => inputPolicies.delete(policy);
    },
    async accept(agent, message, target, wakeup) {
      const operation = acceptance.then(async () => {
        const inputId = message.source?.rpcId ?? message.id;
        const prior = session.log.find(e => e.type === "agent/inbox/spliced" && e.data.inserted.some(m => m.source?.nativeInputId === inputId));
        if(prior){
          const original=prior.data.inserted.find(m=>m.source?.nativeInputId===inputId);
          const admission=session.log.find(event=>event.type==='native/input-accepted'&&event.data.inputId===inputId);
          if(JSON.stringify(original.content)!==JSON.stringify(message.content)||original.source.kind!==message.source?.kind
            ||prior.data.target!==target||(admission?.data.wakeup!==undefined&&admission.data.wakeup!==!!wakeup))throw new NativeBridgeError('NATIVE_INPUT_ID_CONFLICT');
        }
        if (!prior) {
          const accepted = { ...message, source: { ...message.source, nativeInputId: inputId } };
          const preempt=target==='next-step'&&wakeup&&preempts(agent,message)&&!bridge.hardAborted;
          const nextGeneration=session.log.reduce((max,event)=>event.type==='native/input-accepted'
            ?Math.max(max,event.data.preemptGeneration??0):max,bridge.generation)+1;
          if(preempt&&!Number.isSafeInteger(nextGeneration))throw new NativeBridgeError('NATIVE_GENERATION_EXHAUSTED');
          session.append("native/input-accepted", { inputId, messageId: message.id, target, wakeup:!!wakeup,
            ...(preempt?{preemptGeneration:nextGeneration}:{}) });
          agent.inbox.splice(target, Infinity, 0, [accepted]);
        }
        // One barrier may also durably publish inputs whose earlier flush failed.
        await publishDurable(agent,wakeup);
        return { accepted: true, inputId, acceptanceSeq: session.log.find(e => e.type === 'native/input-accepted' && e.data.inputId === inputId)?.seq ?? prior.seq };
      });
      acceptance = operation.catch(() => {});
      return operation;
    },
    async promoteQueued(agent,messageId){
      const operation=acceptance.then(async()=>{
        let promotedMessage;
        const prior=session.log.findLast(event=>event.type==='native/input-accepted'
          &&event.data.action==='promote'&&event.data.messageId===messageId);
        if(!prior){
          const message=agent.inbox.nextTurn.find(row=>row.id===messageId);
          if(!message||!preempts(agent,message)||!message.source.nativeInputId
            ||agent.status!=='running'||bridge.hardAborted)throw new NativeBridgeError('NATIVE_QUEUE_STEER_UNAVAILABLE');
          const inputId=message.source.nativeInputId;
          const original=session.log.find(event=>event.type==='native/input-accepted'&&event.data.inputId===inputId);
          if(!original||original.data.target!=='next-turn')throw new NativeBridgeError('NATIVE_QUEUE_STEER_UNAVAILABLE');
          const generation=session.log.reduce((max,event)=>event.type==='native/input-accepted'
            ?Math.max(max,event.data.preemptGeneration??0):max,bridge.generation)+1;
          if(!Number.isSafeInteger(generation))throw new NativeBridgeError('NATIVE_GENERATION_EXHAUSTED');
          // The inbox fold moves the existing occurrence in this single durable event.
          session.append('native/input-accepted',{inputId,messageId,target:'next-step',wakeup:true,
            action:'promote',priorAcceptanceSeq:original.seq,preemptGeneration:generation});
          promotedMessage=message;
        }
        await publishDurable(agent,true);
        if(promotedMessage)agent.inbox.dispatch.emit('agent/inbox/inserted',{message:promotedMessage});
        return{accepted:true};
      });
      acceptance=operation.catch(()=>{});
      return operation;
    },
    beginSampling(turnSignal, expectedGeneration = bridge.generation) {
      windowGate?.assertReadable();
      const controller = new AbortController();
      sample = controller;
      const generation = expectedGeneration;
      bridge.samplingGeneration = generation;
      // Subscribe before inspecting pending input, including accepted work during preparation.
      const check = () => { if (bridge.generation !== generation) controller.abort(new NativeBridgeError("SAMPLING_PREEMPTED")); };
      const unsubscribe = bridge.subscribe(check);
      check();
      return { generation, signal: AbortSignal.any([turnSignal, controller.signal]), dispose: unsubscribe };
    },
    abortTurn() { bridge.hardAborted = true; sample?.abort(new NativeBridgeError("TURN_ABORTED")); },
    newTurn() { bridge.hardAborted = false; },
    admit(generation) {
      windowGate?.assertReadable();
      if (bridge.hardAborted || writer || generation !== bridge.generation) throw new NativeBridgeError("NATIVE_ADMISSION_CLOSED");
    },
    acquireWriter(expectedSurfaceRevision) {
      const jobs = new Map();
      for (const event of session.log) if (event.type === 'native/ptc-job') jobs.set(event.data.rootCallId, event.data);
      if (writer || bridge.activeEffects || [...jobs.values()].some(row => row.action !== 'consumed') || expectedSurfaceRevision !== bridge.surfaceRevision) throw new NativeBridgeError("NATIVE_WRITER_CAS_CONFLICT");
      writer = Object.freeze({ sessionId: session.id, epoch: ++epoch });
      return writer;
    },
    readWindowSurface(token) {
      if (!writer || token !== writer) throw new NativeBridgeError("NATIVE_STALE_WRITER");
      const nodes = [...session.surfaceManager.nodes];
      return Object.freeze({ nodes: Object.freeze(nodes), messages: Object.freeze(nodes
        .map(seq => session.deriveEventMessage(session.eventAt(seq))).filter(Boolean)) });
    },
    checkAppend(type, opts = {}, data) {
      windowGate?.checkAppend(type, data, opts);
      if (opts.expectedSurfaceRevision !== undefined && opts.expectedSurfaceRevision !== bridge.surfaceRevision) throw new NativeBridgeError("NATIVE_SURFACE_CAS_CONFLICT");
      if (opts.writerToken !== undefined && opts.writerToken !== writer) throw new NativeBridgeError("NATIVE_STALE_WRITER");
      if (writer && type !== "agent/inbox/spliced" && type !== "native/input-accepted" && opts.writerToken !== writer) throw new NativeBridgeError("NATIVE_WRITER_FENCED");
    },
    releaseWriter(token) {
      if (!writer || token !== writer) throw new NativeBridgeError("NATIVE_STALE_WRITER"); writer = undefined;
      if (!windowGate?.isPaused()) for (const agent of deferredWake) { deferredWake.delete(agent); if (!bridge.hardAborted) agent.wakeDriver(); }
    },
  };
  bridges.set(session, bridge);
  return bridge;
}
